mapper.select:
select t.state_msg,t.state_msg stateMsg,t.au_id,t.au_id auId,t.open_id,t.open_id
openId,t.link,t.remark,t.status_cd,t.status_cd statusCd,t.user_id,t.user_id userId,t.room_id,t.room_id
roomId,t.room_name,t.room_name roomName,t.owner_name,t.owner_name ownerName,t.community_name,t.community_name
communityName,t.state,t.community_id,t.community_id communityId,t.member_id,t.member_id memberId
from app_user t
where 1 =1

    and t.state_msg= #{stateMsg}


    and t.au_id= #{auId}


    and t.open_id= #{openId}


    and t.link= #{link}


    and t.remark= #{remark}


    and t.status_cd= #{statusCd}


    and t.user_id= #{userId}


    and t.room_id= #{roomId}


    and t.room_name= #{roomName}


    and t.owner_name= #{ownerName}


    and t.community_name= #{communityName}


    and t.state= #{state}


    and t.community_id= #{communityId}


    and t.member_id= #{memberId}

order by t.create_time desc

    limit #{page}, #{row}

